const extraStageBefore=stage;stage=function(w){if(w.gameType==='memory')return `<div class="slice mini-game memory-game" data-mini="memory"><div class="mini-label">MEMORY GARDEN</div><div class="memory-grid">${Array.from({length:12},(_,i)=>`<button data-flip="${i}" aria-label="翻开第 ${i+1} 张卡">✿</button>`).join('')}</div><div class="mini-footer"><span data-game-status role="status">找到 6 对花朵</span><button data-game-reset>重新开始</button></div></div>`;if(w.gameType==='lights')return `<div class="slice mini-game lights-game" data-mini="lights"><div class="mini-label">LIGHTS OUT · 熄灭所有灯</div><div class="lights-grid">${Array.from({length:9},(_,i)=>`<button data-light="${i}" aria-label="第 ${i+1} 盏灯"></button>`).join('')}</div><div class="mini-footer"><span data-game-status role="status">点击会影响相邻灯</span><button data-game-reset>重来</button></div></div>`;if(w.gameType==='reaction')return '<div class="slice mini-game reaction-game" data-mini="reaction"><div class="mini-label">WAIT FOR GREEN</div><button class="reaction-target" data-reaction>点击开始</button><div class="mini-footer"><span data-game-status role="status">变绿后，尽快点击</span><button data-game-reset>重置</button></div></div>';if(w.id==='daily-walk')return '<div class="slice quiet-photo"><img src="assets/evening-walk.jpg" alt="傍晚街道上的行人与狗" loading="lazy"><span>下班之后 / 慢一点也没关系</span></div>';if(w.id==='daily-dinner')return '<div class="slice serving-recipe"><span class="mini-label">阿宁的厨房 · 番茄鸡蛋面</span><h3>今晚，几个人吃？</h3><div class="serving-picker"><button data-serving="-1" aria-label="减少一人">−</button><output>1 人份</output><button data-serving="1" aria-label="增加一人">＋</button></div><p data-ingredients>番茄 2 个 · 鸡蛋 2 个<br>面条 100 g · 水 400 ml</p><small>点开看做法 · 用量仅作参考，按口味调整</small></div>';if(w.lifeType==='letter')return '<div class="slice life-letter"><span>SUNDAY NOTES / 09</span><p>今天的进度：<br>洗好的床单。<br>一通很长的电话。<br>十页书。</p><small>没有完成清单，也过了很好的一天。</small></div>';if(w.lifeType==='plant')return `<div class="slice plant-diary"><span class="mini-label">窗边观察日记 · 示意插画</span><div class="plant-picture" data-growth="new"><span>🌱</span></div><p data-plant-caption>9 月 20 日 · 新叶展开了</p><div><button data-plant="old">9/06 · 刚搬来</button><button data-plant="new" aria-pressed="true">9/20 · 新叶</button></div></div>`;if(w.lifeType==='flowers')return '<div class="slice flower-note"><span>MARKET FINDS / 手记插画</span><div class="flower-drawing">✿<i>✿</i>✿<b>▱</b></div><p>五块钱的小花，<br>住进了果酱罐。</p></div>';return extraStageBefore(w)};
function initializeMiniGames(root){root.querySelectorAll('[data-mini]').forEach(el=>{if(el.dataset.ready)return;el.dataset.ready='1';const status=el.querySelector('[data-game-status]');let timer,phase='idle',started=0,attempts=[],deck=[],opened=[],matched=new Set(),steps=0,locked=false,lights=[];const flipLight=i=>{[i,i%3>0?i-1:-1,i%3<2?i+1:-1,i-3,i+3].filter(j=>j>=0&&j<9).forEach(j=>lights[j]=!lights[j])};function reset(){clearTimeout(timer);phase='idle';attempts=[];steps=0;locked=false;opened=[];matched=new Set();if(el.dataset.mini==='memory'){deck=['🌼','🌷','🌻','🌸','🍀','🌺','🌼','🌷','🌻','🌸','🍀','🌺'];for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}el.querySelectorAll('[data-flip]').forEach(b=>{b.textContent='✿';b.disabled=false;b.classList.remove('matched')});status.textContent='找到 6 对花朵'}if(el.dataset.mini==='lights'){lights=Array(9).fill(false);[0,4,8].forEach(flipLight);paintLights();status.textContent='点击会影响相邻灯'}if(el.dataset.mini==='reaction'){el.querySelector('[data-reaction]').textContent='点击开始';el.classList.remove('signal-green');status.textContent='变绿后，尽快点击'}}function paintLights(){el.querySelectorAll('[data-light]').forEach(b=>{b.classList.toggle('lit',lights[+b.dataset.light]);b.setAttribute('aria-pressed',String(lights[+b.dataset.light]))})}el.querySelector('[data-game-reset]').onclick=reset;el.querySelectorAll('[data-flip]').forEach(b=>b.onclick=()=>{const i=+b.dataset.flip;if(locked||matched.has(i)||opened.includes(i))return;b.textContent=deck[i];opened.push(i);if(opened.length===2){steps++;const [a,c]=opened;if(deck[a]===deck[c]){matched.add(a);matched.add(c);opened=[];[a,c].forEach(j=>{const card=el.querySelector(`[data-flip="${j}"]`);card.classList.add('matched');card.disabled=true});status.textContent=matched.size===12?`完成！用了 ${steps} 步`:`${matched.size/2} / 6 对 · ${steps} 步`}else{locked=true;timer=setTimeout(()=>{opened.forEach(j=>el.querySelector(`[data-flip="${j}"]`).textContent='✿');opened=[];locked=false},750);status.textContent=`${matched.size/2} / 6 对 · ${steps} 步`}}});el.querySelectorAll('[data-light]').forEach(b=>b.onclick=()=>{if(phase==='done')return;steps++;flipLight(+b.dataset.light);paintLights();if(lights.every(x=>!x)){phase='done';status.textContent=`全部熄灭！${steps} 步完成`}else status.textContent=`${steps} 步 · 还有 ${lights.filter(Boolean).length} 盏灯`});el.querySelector('[data-reaction]')?.addEventListener('click',()=>{const b=el.querySelector('[data-reaction]');if(phase==='waiting'){clearTimeout(timer);phase='idle';b.textContent='抢跑了，再试一次';return}if(phase==='go'){const ms=Math.round(performance.now()-started);attempts.push(ms);phase='idle';el.classList.remove('signal-green');b.textContent=ms+' ms · 再试一次';status.textContent=`${attempts.length} 次尝试 · 最快 ${Math.min(...attempts)} ms`;return}phase='waiting';b.textContent='等待变绿…';timer=setTimeout(()=>{if(!el.isConnected)return;phase='go';started=performance.now();el.classList.add('signal-green');b.textContent='现在点击！'},1200+Math.random()*2000)});reset()})}
const miniInitBefore=initStages;initStages=function(root){miniInitBefore(root);initializeMiniGames(root)};
document.addEventListener('click',e=>{const serving=e.target.closest('[data-serving]');if(serving){const el=serving.closest('.serving-recipe'),n=Math.min(6,Math.max(1,+(el.dataset.servings||1)+ +serving.dataset.serving));el.dataset.servings=n;el.querySelector('output').textContent=n+' 人份';el.querySelector('[data-ingredients]').innerHTML=`番茄 ${2*n} 个 · 鸡蛋 ${2*n} 个<br>面条 ${100*n} g · 水 ${400*n} ml`}const plant=e.target.closest('[data-plant]');if(plant){const el=plant.closest('.plant-diary'),old=plant.dataset.plant==='old';el.querySelector('[data-growth]').dataset.growth=old?'old':'new';el.querySelector('[data-plant-caption]').textContent=old?'9 月 6 日 · 只有两片小叶子':'9 月 20 日 · 新叶展开了';el.querySelectorAll('[data-plant]').forEach(b=>b.setAttribute('aria-pressed',String(b===plant)))}});
const lifeOpenBefore=openWork;openWork=function(id,remix=false){const w=works.find(x=>x.id===id);lifeOpenBefore(id,remix);if(w?.lifeType&&!remix){document.querySelector('#dialog-desc').textContent=w.body;document.querySelector('#dialog-desc').style.whiteSpace='pre-line';document.querySelector('#dialog-mode').textContent='LIFE NOTES · 虚构生活示例'}if(w?.gameType&&!remix)document.querySelector('#dialog-mode').textContent='PLAYGROUND · '+w.time};
